<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Laughing yellow blob</title>
<style>
  html, body { margin: 0; padding: 0; width: 240px; height: 240px; overflow: hidden; background: #e7e1d8; }
  canvas { display: block; position: absolute; left: 0; top: 0; width: 240px; height: 240px; }
</style>
</head>
<body>
<script type="module">
import * as THREE from 'three';
import { RoundedBoxGeometry } from 'three/addons/geometries/RoundedBoxGeometry.js';

const W = 240, HGT = 240, PERIOD = 3670, BASE_Y = 3.5;

const renderer = new THREE.WebGLRenderer({ preserveDrawingBuffer: true });
renderer.setPixelRatio(1);
renderer.setSize(W, HGT);
document.body.appendChild(renderer.domElement);

const scene = new THREE.Scene();
scene.background = new THREE.Color('#e7e1d8');

const camera = new THREE.PerspectiveCamera(35, 1, 0.1, 100);
camera.position.set(0, BASE_Y, 6);
camera.lookAt(0, BASE_Y, 0);

// ---------- lights (readable from every side)
scene.add(new THREE.HemisphereLight(0xffffff, 0xd8c0a0, 1.7));
scene.add(new THREE.AmbientLight(0xffffff, 0.35));
const keyLight = new THREE.DirectionalLight(0xfff8ee, 2.2); keyLight.position.set(-3, 5, 6); scene.add(keyLight);
const backLight1 = new THREE.DirectionalLight(0xffffff, 1.0); backLight1.position.set(4, 3, -6); scene.add(backLight1);
const backLight2 = new THREE.DirectionalLight(0xffffff, 0.6); backLight2.position.set(-6, 2, -3); scene.add(backLight2);

// ---------- helpers
const clamp01 = (x) => (x < 0 ? 0 : x > 1 ? 1 : x);
const ss = (a, b, x) => { const t = clamp01((x - a) / (b - a)); return t * t * (3 - 2 * t); };
let seed = 20251;
const rnd = () => { seed = (seed * 1664525 + 1013904223) >>> 0; return seed / 4294967296; };
const lam = (c) => new THREE.MeshLambertMaterial({ color: c });
function addBox(parent, w, h, d, mat, x, y, z) {
  const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
  m.position.set(x, y, z); parent.add(m); return m;
}

// ---------- background room
const bg = new THREE.Group(); bg.name = 'background'; scene.add(bg);
{
  const cv = document.createElement('canvas'); cv.width = 64; cv.height = 64;
  const cx = cv.getContext('2d');
  cx.fillStyle = '#e7e1d8'; cx.fillRect(0, 0, 64, 64);
  const gr = cx.createRadialGradient(24, 22, 1, 24, 22, 26);
  gr.addColorStop(0, 'rgba(255,243,240,1)'); gr.addColorStop(1, 'rgba(255,243,240,0)');
  cx.fillStyle = gr; cx.fillRect(0, 0, 64, 64);
  const wallTex = new THREE.CanvasTexture(cv); wallTex.colorSpace = THREE.SRGBColorSpace;
  const wall = new THREE.Mesh(new THREE.PlaneGeometry(16, 10), new THREE.MeshBasicMaterial({ map: wallTex }));
  wall.name = 'wall'; wall.position.set(0, 5, -5); bg.add(wall);

  const floor = new THREE.Mesh(new THREE.PlaneGeometry(16, 16), lam('#cdc3b3'));
  floor.name = 'floor'; floor.rotation.x = -Math.PI / 2; floor.position.set(0, 0, 3); bg.add(floor);

  // bookshelf
  const shelf = new THREE.Group(); shelf.name = 'bookshelf'; bg.add(shelf);
  const wood = lam('#7b5433'), woodDark = lam('#48311f');
  const SX = -3.06, SZ = -4.3, SW = 1.68, SY0 = 1.2, SY1 = 5.95;
  addBox(shelf, SW, SY1 - SY0, 0.05, woodDark, SX, (SY0 + SY1) / 2, SZ - 0.3);
  addBox(shelf, 0.09, SY1 - SY0, 0.62, wood, SX + SW / 2 - 0.045, (SY0 + SY1) / 2, SZ);
  addBox(shelf, 0.09, SY1 - SY0, 0.62, wood, SX - SW / 2 + 0.045, (SY0 + SY1) / 2, SZ);
  for (let k = 0; k < 7; k++) addBox(shelf, SW, 0.07, 0.62, wood, SX, SY0 + 0.035 + k * 0.775, SZ);
  const bookCols = ['#f1ece4', '#ddd6cb', '#c9b79c', '#8f6a4a', '#ebe4d8'];
  const bookMats = bookCols.map(lam);
  for (let k = 0; k < 6; k++) {
    let x = SX + SW / 2 - 0.13;
    const yb = SY0 + 0.07 + k * 0.775;
    const n = 3 + Math.floor(rnd() * 5);
    for (let b = 0; b < n; b++) {
      const bw = 0.09 + rnd() * 0.08, bh = 0.4 + rnd() * 0.22;
      const mat = bookMats[Math.floor(rnd() * bookMats.length)];
      if (x - bw < SX - SW / 2 + 0.13) break;
      addBox(shelf, bw, bh, 0.4, mat, x - bw / 2, yb + bh / 2, SZ + 0.05);
      x -= bw + 0.012;
    }
  }
  addBox(shelf, 1.7, 1.2, 0.66, lam('#e9e4dc'), SX, 0.6, SZ);

  // plant on a little wall shelf
  const plant = new THREE.Group(); plant.name = 'plant'; plant.position.set(-1.45, 3.0, -4.6); bg.add(plant);
  addBox(plant, 0.9, 0.05, 0.4, lam('#e6dfd4'), 0, -0.03, -0.1);
  const pot = new THREE.Mesh(new THREE.CylinderGeometry(0.12, 0.09, 0.2, 12), lam('#cfc9c0'));
  pot.position.y = 0.1; plant.add(pot);
  const leafMat = lam('#567f3e');
  [[0, 0.38, 0, 0.17], [-0.13, 0.3, 0.02, 0.12], [0.13, 0.32, 0, 0.12], [0.03, 0.5, 0, 0.1]].forEach((l) => {
    const s = new THREE.Mesh(new THREE.SphereGeometry(l[3], 10, 8), leafMat);
    s.position.set(l[0], l[1], l[2]); plant.add(s);
  });

  // floor lamp
  const lamp = new THREE.Group(); lamp.name = 'lamp'; lamp.position.set(1.58, 0, -4.4); bg.add(lamp);
  const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.025, 0.025, 4.0, 8), lam('#6b665e'));
  pole.position.y = 2.0; lamp.add(pole);
  const shade = new THREE.Mesh(new THREE.CylinderGeometry(0.18, 0.28, 0.42, 16), lam('#b8b0a2'));
  shade.position.y = 4.18; lamp.add(shade);

  // curtain
  const curtain = new THREE.Group(); curtain.name = 'curtain'; bg.add(curtain);
  ['#8f8a82', '#b9b4ab', '#cfcac1', '#aaa59c', '#c6c1b8'].forEach((c, k) => {
    const cyl = new THREE.Mesh(new THREE.CylinderGeometry(0.2, 0.2, 9, 12), lam(c));
    cyl.position.set(2.2 + 0.36 * k, 4.5, -4.2); curtain.add(cyl);
  });

  // sofa
  const sofa = new THREE.Group(); sofa.name = 'sofa'; bg.add(sofa);
  const sofaMat = lam('#e9e5df');
  const sb = new THREE.Mesh(new RoundedBoxGeometry(2.4, 1.3, 0.7, 3, 0.18), sofaMat);
  sb.position.set(3.2, 2.15, -2.9); sofa.add(sb);
  const seat = new THREE.Mesh(new RoundedBoxGeometry(2.4, 1.0, 1.5, 3, 0.18), sofaMat);
  seat.position.set(3.2, 0.95, -2.3); sofa.add(seat);
  const cushion = new THREE.Mesh(new THREE.SphereGeometry(0.32, 12, 10), lam('#77726a'));
  cushion.scale.set(1, 0.8, 0.5); cushion.position.set(2.45, 2.75, -2.55); sofa.add(cushion);
}

// ---------- character: lathe-like blob body (profile bottom -> top), y=0 at image centre
const ctrl = [
  [0, -3.5], [0.55, -3.46], [1.0, -3.32], [1.32, -3.08], [1.52, -2.75], [1.63, -2.3],
  [1.66, -1.85], [1.62, -1.4], [1.52, -1.0], [1.36, -0.68], [1.15, -0.42], [0.95, -0.22],
  [0.82, -0.05], [0.76, 0.12], [0.73, 0.32], [0.715, 0.52], [0.69, 0.72], [0.63, 0.92],
  [0.52, 1.08], [0.36, 1.2], [0.18, 1.27], [0, 1.29]
];
const profCurve = new THREE.CatmullRomCurve3(ctrl.map((p) => new THREE.Vector3(p[0], p[1], 0)), false, 'centripetal');
const NP = 112;
const prof = profCurve.getPoints(NP - 1).map((p) => ({ r: Math.max(0, p.x), y: p.y }));
prof[0].r = 0; prof[NP - 1].r = 0;

const szOf = (y) => 1 - 0.16 * ss(0.0, -1.3, y);
function Rof(y) {
  for (let j = NP - 2; j >= 0; j--) {
    if (prof[j].y <= y) {
      const a = prof[j], b = prof[j + 1];
      const t = clamp01((y - a.y) / Math.max(1e-6, b.y - a.y));
      return a.r + (b.r - a.r) * t;
    }
  }
  return prof[0].r;
}

const MSEG = 128;
const NV = (MSEG + 1) * NP;
const fpos = new Float32Array(NV * 3), fcol = new Float32Array(NV * 3);
for (let i = 0; i <= MSEG; i++) {
  const phi = ((i % MSEG) / MSEG) * Math.PI * 2;
  const s = Math.sin(phi), c = Math.cos(phi);
  for (let j = 0; j < NP; j++) {
    const k = (i * NP + j) * 3, r = prof[j].r, y = prof[j].y;
    fpos[k] = r * s; fpos[k + 1] = y; fpos[k + 2] = r * c * szOf(y);
  }
}
const fullIdx = [];
for (let i = 0; i < MSEG; i++) for (let j = 0; j < NP - 1; j++) {
  const a = i * NP + j, b = (i + 1) * NP + j, c = b + 1, d = a + 1;
  fullIdx.push(a, b, c, a, c, d);
}
const fullGeo = new THREE.BufferGeometry();
fullGeo.setAttribute('position', new THREE.BufferAttribute(fpos, 3));
fullGeo.setIndex(fullIdx);
fullGeo.computeVertexNormals();
const fnor = fullGeo.attributes.normal.array;
for (let j = 0; j < NP; j++) { // weld seam normals
  const a = j * 3, b = (MSEG * NP + j) * 3;
  let x = fnor[a] + fnor[b], y = fnor[a + 1] + fnor[b + 1], z = fnor[a + 2] + fnor[b + 2];
  const l = Math.hypot(x, y, z) || 1; x /= l; y /= l; z /= l;
  fnor[a] = fnor[b] = x; fnor[a + 1] = fnor[b + 1] = y; fnor[a + 2] = fnor[b + 2] = z;
}
for (let i = 0; i <= MSEG; i++) { // poles
  const a = (i * NP) * 3, b = (i * NP + NP - 1) * 3;
  fnor[a] = 0; fnor[a + 1] = -1; fnor[a + 2] = 0;
  fnor[b] = 0; fnor[b + 1] = 1; fnor[b + 2] = 0;
}
const yellow = new THREE.Color('#f5d020');
const cream = new THREE.Color('#f6e6cf');
for (let v = 0; v < NV; v++) {
  const k = v * 3, x = fpos[k], y = fpos[k + 1], z = fpos[k + 2];
  const d = (x / 1.02) * (x / 1.02) + ((y + 2.05) / 1.58) * ((y + 2.05) / 1.58);
  const m = (1 - ss(0.8, 1.06, d)) * ss(0.05, 0.4, z);
  fcol[k] = yellow.r + (cream.r - yellow.r) * m;
  fcol[k + 1] = yellow.g + (cream.g - yellow.g) * m;
  fcol[k + 2] = yellow.b + (cream.b - yellow.b) * m;
}
function subGeo(j0, j1) {
  const n = j1 - j0 + 1, cnt = (MSEG + 1) * n;
  const p = new Float32Array(cnt * 3), nn = new Float32Array(cnt * 3), cc = new Float32Array(cnt * 3);
  for (let i = 0; i <= MSEG; i++) for (let jj = 0; jj < n; jj++) {
    const s = (i * NP + j0 + jj) * 3, d = (i * n + jj) * 3;
    for (let q = 0; q < 3; q++) { p[d + q] = fpos[s + q]; nn[d + q] = fnor[s + q]; cc[d + q] = fcol[s + q]; }
  }
  const idx = [];
  for (let i = 0; i < MSEG; i++) for (let jj = 0; jj < n - 1; jj++) {
    const a = i * n + jj, b = (i + 1) * n + jj, c = b + 1, d = a + 1;
    idx.push(a, b, c, a, c, d);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(p, 3));
  g.setAttribute('normal', new THREE.BufferAttribute(nn, 3));
  g.setAttribute('color', new THREE.BufferAttribute(cc, 3));
  g.setIndex(idx);
  return g;
}
const RIGID_Y = -0.25, FIXED_Y = -2.5;
let jSplit = 0;
while (jSplit < NP - 4 && prof[jSplit].y < -0.2) jSplit++;
const torsoGeo = subGeo(0, jSplit + 2);
const headGeo = subGeo(jSplit, NP - 1);
const tP0 = torsoGeo.attributes.position.array.slice();
const tN0 = torsoGeo.attributes.normal.array.slice();
const tCount = tP0.length / 3;
const tW = new Float32Array(tCount);
for (let v = 0; v < tCount; v++) tW[v] = ss(FIXED_Y, RIGID_Y, tP0[v * 3 + 1]);

const skinMat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.48, metalness: 0 });
const armMat = new THREE.MeshStandardMaterial({ color: yellow, roughness: 0.48, metalness: 0 });
const handMat = new THREE.MeshStandardMaterial({ color: '#3b3a1e', roughness: 0.6, metalness: 0 });

const character = new THREE.Group(); character.name = 'character-yellow-blob';
character.position.set(0.06, BASE_Y, 0);
scene.add(character);

const bodyG = new THREE.Group(); bodyG.name = 'body'; character.add(bodyG);
const torsoMesh = new THREE.Mesh(torsoGeo, skinMat); torsoMesh.name = 'torso-skin'; bodyG.add(torsoMesh);

const headG = new THREE.Group(); headG.name = 'head'; character.add(headG);
const headMesh = new THREE.Mesh(headGeo, skinMat); headMesh.name = 'head-skin'; headG.add(headMesh);

// ---------- eyes
const eyesG = new THREE.Group(); eyesG.name = 'eyes'; headG.add(eyesG);
const rimMat = new THREE.MeshStandardMaterial({ color: '#e3e3c0', roughness: 0.5 });
const irisMat = new THREE.MeshStandardMaterial({ color: '#2c4320', roughness: 0.35 });
const pupilMat = new THREE.MeshStandardMaterial({ color: '#080b06', roughness: 0.3 });
const glintMat = new THREE.MeshBasicMaterial({ color: '#ffffff' });
const lidMat = new THREE.MeshStandardMaterial({ color: '#5d6128', roughness: 0.6 });
const lashMat = new THREE.MeshStandardMaterial({ color: '#272d10', roughness: 0.6 });
const unitSphere = new THREE.SphereGeometry(1, 24, 16);
function makeEye(sign) {
  const g = new THREE.Group(); g.name = sign > 0 ? 'eye-left' : 'eye-right';
  const phi = sign * 0.53, y = 0.71, r = Rof(y) - 0.012;
  g.position.set(r * Math.sin(phi), y, r * Math.cos(phi));
  g.rotation.order = 'YXZ'; g.rotation.set(-0.26, phi, 0);
  const open = new THREE.Group(); open.name = g.name + '-ball';
  const rim = new THREE.Mesh(unitSphere, rimMat); rim.scale.set(0.1, 0.1, 0.035); open.add(rim);
  const iris = new THREE.Mesh(unitSphere, irisMat); iris.scale.set(0.08, 0.08, 0.04); iris.position.z = 0.012; open.add(iris);
  const pupil = new THREE.Mesh(unitSphere, pupilMat); pupil.scale.set(0.045, 0.045, 0.0225); pupil.position.z = 0.036; open.add(pupil);
  const glint = new THREE.Mesh(unitSphere, glintMat); glint.scale.setScalar(0.014); glint.position.set(-0.022, 0.028, 0.058); open.add(glint);
  const lid = new THREE.Group(); lid.name = g.name + '-lid';
  const lidM = new THREE.Mesh(unitSphere, lidMat); lidM.scale.set(0.15, 0.052, 0.045); lid.add(lidM);
  const lash = new THREE.Mesh(unitSphere, lashMat); lash.scale.set(0.14, 0.012, 0.052); lid.add(lash);
  g.add(open, lid); eyesG.add(g);
  return { g, open, lid };
}
const eyes = [makeEye(-1), makeEye(1)];

// ---------- mouth (surface patches re-shaped every frame)
const mouthG = new THREE.Group(); mouthG.name = 'mouth'; headG.add(mouthG);
function makePatch(nu, nv, mat, name) {
  const n = (nu + 1) * (nv + 1);
  const geo = new THREE.BufferGeometry();
  const pos = new Float32Array(n * 3), nor = new Float32Array(n * 3);
  const idx = [];
  for (let iu = 0; iu < nu; iu++) for (let iv = 0; iv < nv; iv++) {
    const a = iu * (nv + 1) + iv, b = (iu + 1) * (nv + 1) + iv, c = b + 1, d = a + 1;
    idx.push(a, d, c, a, c, b);
  }
  geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  geo.setAttribute('normal', new THREE.BufferAttribute(nor, 3));
  geo.setIndex(idx);
  const mesh = new THREE.Mesh(geo, mat); mesh.name = name; mesh.frustumCulled = false;
  mouthG.add(mesh);
  return { geo, pos, nor, nu, nv, mesh };
}
function setPatch(p, phiMax, topFn, botFn, eps) {
  const pos = p.pos, nor = p.nor, nu = p.nu, nv = p.nv; let k = 0;
  for (let iu = 0; iu <= nu; iu++) {
    const u = -1 + (2 * iu) / nu, phi = u * phiMax, s = Math.sin(phi), c = Math.cos(phi);
    const yt = topFn(u), yb = botFn(u);
    for (let iv = 0; iv <= nv; iv++) {
      const y = yt + (yb - yt) * (iv / nv), r = Rof(y) + eps;
      pos[k] = r * s; pos[k + 1] = y; pos[k + 2] = r * c * szOf(y);
      nor[k] = s * 0.99; nor[k + 1] = 0.12; nor[k + 2] = c * 0.99;
      k += 3;
    }
  }
  p.geo.attributes.position.needsUpdate = true;
  p.geo.attributes.normal.needsUpdate = true;
  p.geo.computeBoundingBox(); p.geo.computeBoundingSphere();
}
const cavity = makePatch(28, 8, new THREE.MeshStandardMaterial({ color: '#3a0d0b', roughness: 0.9, side: THREE.DoubleSide }), 'mouth-cavity');
const teeth = makePatch(24, 4, new THREE.MeshStandardMaterial({ color: '#fffdf6', roughness: 0.35, side: THREE.DoubleSide }), 'teeth');
const tongue = makePatch(14, 4, new THREE.MeshStandardMaterial({ color: '#c9544f', roughness: 0.6, side: THREE.DoubleSide }), 'tongue');
const PHI_M = 0.40;
const shapeF = (u) => Math.pow(Math.max(0, 1 - u * u), 0.55);
function updateMouth(o) {
  const h = 0.11 + 0.26 * o, ym = 0.30 + 0.06 * o, cr = 0.045;
  const yU = (u) => ym + cr * u * u;
  const yL = (u) => yU(u) - h * shapeF(u);
  setPatch(cavity, PHI_M * 1.05, (u) => yU(u) + 0.014, (u) => yL(u) - 0.014, 0.010);
  const k = ss(0.05, 0.3, o);
  const tT = (0.84 * h - 0.01) * (1 - k) + 0.085 * k;
  setPatch(teeth, PHI_M * 0.92, (u) => yU(0.92 * u) - 0.006, (u) => yU(0.92 * u) - 0.006 - Math.max(0.002, tT * shapeF(u)), 0.018);
  const tH = 0.5 * h * ss(0.3, 0.85, o);
  tongue.mesh.visible = tH > 0.012;
  setPatch(tongue, PHI_M * 0.6, (u) => yL(0.6 * u) + 0.008 + tH * Math.sqrt(Math.max(0, 1 - u * u)) + 0.001, (u) => yL(0.6 * u) + 0.008, 0.015);
}

// ---------- arms and hands
const armsG = new THREE.Group(); armsG.name = 'arms'; character.add(armsG);
function makeArm(sign) {
  const g = new THREE.Group(); g.name = sign > 0 ? 'arm-left' : 'arm-right';
  const limb = new THREE.Mesh(unitSphere, armMat); limb.name = g.name + '-limb';
  const hand = new THREE.Group(); hand.name = sign > 0 ? 'hand-left' : 'hand-right';
  const palm = new THREE.Mesh(unitSphere, handMat); palm.scale.set(0.24, 0.17, 0.2); hand.add(palm);
  const thumb = new THREE.Mesh(unitSphere, handMat); thumb.scale.setScalar(0.09); thumb.position.set(-sign * 0.14, 0.1, 0.05); hand.add(thumb);
  for (let f = -1; f <= 1; f++) {
    const kn = new THREE.Mesh(unitSphere, handMat); kn.scale.setScalar(0.08);
    kn.position.set(f * 0.13, -0.07, 0.14); hand.add(kn);
  }
  hand.rotation.set(0.15, -sign * 0.25, sign * 0.2);
  g.add(limb, hand); armsG.add(g);
  return { limb, hand, shoulder: new THREE.Vector3(sign * 1.2, -0.72, 0.1) };
}
const armR = makeArm(-1); // character's right, viewer's left
const armL = makeArm(1);  // character's left, viewer's right

// ---------- animation tracks (keyframes at the GIF sample times, loop closes at 3670)
const KT = [0, 530, 1000, 1530, 2070, 2600, 3070, 3600, 3670];
function makeTrack(vals) {
  const v = vals.concat([vals[0]]);
  const m = new Array(9).fill(0);
  for (let i = 1; i <= 6; i++) m[i] = (v[i + 1] - v[i - 1]) / (KT[i + 1] - KT[i - 1]);
  return { v, m };
}
function evalTrack(tr, t) {
  let i = 0; while (i < 7 && t >= KT[i + 1]) i++;
  const t0 = KT[i], dt = KT[i + 1] - t0, s = (t - t0) / dt, s2 = s * s, s3 = s2 * s;
  return (2 * s3 - 3 * s2 + 1) * tr.v[i] + (s3 - 2 * s2 + s) * dt * tr.m[i]
       + (-2 * s3 + 3 * s2) * tr.v[i + 1] + (s3 - s2) * dt * tr.m[i + 1];
}
function evalStep(keys, t) {
  let i = 0; while (i < keys.length - 2 && t >= keys[i + 1][0]) i++;
  const a = keys[i], b = keys[i + 1];
  let s = clamp01((t - a[0]) / (b[0] - a[0])); s = s * s * (3 - 2 * s);
  return a[1] + (b[1] - a[1]) * s;
}
const PXU = 1 / 63.5;
const TR = {
  hx: makeTrack([8, 12, 3, 0, 4, -8, -8, -14].map((v) => v * PXU)),
  hy: makeTrack([0, 0, 0, -4, -2, 0, 0, -7].map((v) => v * PXU)),
  yaw: makeTrack([9, 5, 14, -8, 10, -10, -10, -6]),
  pitch: makeTrack([0, 0, 1, 2, 11, 11, 11, 5]),
  roll: makeTrack([0, 2, 4, 5, 3, -1, -1, 3]),
  open: makeTrack([0.35, 0.2, 0.4, 0.6, 1, 0.05, 0.05, 0.15]),
  rhx: makeTrack([-1.16, -1.42, -1.16, -1.16, -1.23, -1.10, -1.10, -1.33]),
  rhy: makeTrack([-1.32, -1.45, -1.23, -1.32, -0.97, -1.32, -1.40, -1.36]),
  lhx: makeTrack([1.17, 1.72, 1.70, 1.30, 1.26, 1.30, 1.34, 1.72]),
  lhy: makeTrack([-1.36, -1.75, -1.72, -1.23, -0.91, -1.10, -1.17, -1.75])
};
const BLINK = [[0, 1], [220, 1], [380, 0], [1240, 0], [1400, 1], [3280, 1], [3440, 0], [3615, 0], [3670, 1]];

// ---------- posing
const PIV = new THREE.Vector3(0, 0.5, 0);
const _e = new THREE.Euler(0, 0, 0, 'YXZ'), _q = new THREE.Quaternion(), _m = new THREE.Matrix4();
const _p = new THREE.Vector3(), _one = new THREE.Vector3(1, 1, 1);
const _S = new THREE.Vector3(), _T = new THREE.Vector3(), _Hd = new THREE.Vector3(), _D = new THREE.Vector3();
const UP = new THREE.Vector3(0, 1, 0);
const D2R = Math.PI / 180;

function skinTorso(m) {
  const e = m.elements;
  const P = torsoGeo.attributes.position.array, N = torsoGeo.attributes.normal.array;
  for (let v = 0, k = 0; v < tCount; v++, k += 3) {
    const w = tW[v];
    const x = tP0[k], y = tP0[k + 1], z = tP0[k + 2];
    const nx = tN0[k], ny = tN0[k + 1], nz = tN0[k + 2];
    if (w === 0) { P[k] = x; P[k + 1] = y; P[k + 2] = z; N[k] = nx; N[k + 1] = ny; N[k + 2] = nz; continue; }
    const tx = e[0] * x + e[4] * y + e[8] * z + e[12];
    const ty = e[1] * x + e[5] * y + e[9] * z + e[13];
    const tz = e[2] * x + e[6] * y + e[10] * z + e[14];
    P[k] = x + (tx - x) * w; P[k + 1] = y + (ty - y) * w; P[k + 2] = z + (tz - z) * w;
    const rx = e[0] * nx + e[4] * ny + e[8] * nz;
    const ry = e[1] * nx + e[5] * ny + e[9] * nz;
    const rz = e[2] * nx + e[6] * ny + e[10] * nz;
    const ax = nx + (rx - nx) * w, ay = ny + (ry - ny) * w, az = nz + (rz - nz) * w;
    const il = 1 / (Math.hypot(ax, ay, az) || 1);
    N[k] = ax * il; N[k + 1] = ay * il; N[k + 2] = az * il;
  }
  torsoGeo.attributes.position.needsUpdate = true;
  torsoGeo.attributes.normal.needsUpdate = true;
  torsoGeo.computeBoundingBox(); torsoGeo.computeBoundingSphere();
}

function poseArm(arm, hx, hy, hz, m) {
  _S.copy(arm.shoulder);
  const w = ss(FIXED_Y, RIGID_Y, _S.y);
  _T.copy(_S).applyMatrix4(m); _S.lerp(_T, w);
  _Hd.set(hx, hy, hz);
  _D.subVectors(_Hd, _S);
  const L = Math.max(0.05, _D.length()); _D.divideScalar(L);
  arm.limb.position.copy(_S).addScaledVector(_D, (L - 0.14) / 2);
  arm.limb.scale.set(0.3, (L + 0.2) / 2, 0.3);
  arm.limb.quaternion.setFromUnitVectors(UP, _D);
  arm.hand.position.copy(_Hd);
}

function pose(t) {
  const hx = evalTrack(TR.hx, t), hy = evalTrack(TR.hy, t);
  const yaw = evalTrack(TR.yaw, t) * D2R, pitch = evalTrack(TR.pitch, t) * D2R, roll = evalTrack(TR.roll, t) * D2R;
  _e.set(-pitch, yaw, roll, 'YXZ'); _q.setFromEuler(_e);
  _p.copy(PIV).applyQuaternion(_q).negate().add(PIV); _p.x += hx; _p.y += hy;
  _m.compose(_p, _q, _one);
  headG.position.copy(_p); headG.quaternion.copy(_q);
  skinTorso(_m);

  const b = clamp01(evalStep(BLINK, t));
  for (const e of eyes) {
    e.open.visible = b < 0.97; e.open.scale.y = Math.max(0.03, 1 - b);
    e.lid.visible = b > 0.03; e.lid.scale.set(0.75 + 0.25 * b, Math.max(0.05, b), 0.6 + 0.4 * b);
  }

  updateMouth(clamp01(evalTrack(TR.open, t)));

  poseArm(armR, evalTrack(TR.rhx, t), evalTrack(TR.rhy, t), 1.0, _m);
  poseArm(armL, evalTrack(TR.lhx, t), evalTrack(TR.lhy, t), 1.0, _m);
}

function render(t) {
  let tt = Number(t); if (!Number.isFinite(tt)) tt = 0;
  tt = ((tt % PERIOD) + PERIOD) % PERIOD;
  pose(tt);
  renderer.render(scene, camera);
}

render(0);
window.nwb = { scene, renderer, cameras: { ref: camera }, characters: [character], render, ready: true };
</script>
</body>
</html>
```

- **Character:** one closed blob volume with a cream belly, split into a rigid `head` mesh and a torso whose vertices bend with the head, so the neck stays seamless as it sways. Nested named groups cover `body`, `head`, `eyes`, `mouth`, `arms` and each hand.
- **Motion:** head sway, yaw, pitch and roll, mouth opening and hand positions are keyed at the eight GIF times and wrap at exactly 3670 ms. The eyes are closed at 0, open by 530, closed again from about 1400, and open at 3600. The last 70 ms snaps back to the first-frame pose, mirroring the jump in the GIF itself.
- **Room:** bookshelf, wall plant, lamp, curtain and sofa are built from primitives and kept outside the character group.

One deliberate choice: the renderer is created with exactly the contract's arguments, so there is no antialiasing and edges will be slightly jagged.
